using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class HospitalSideUVFinish{static HospitalSideUVFinish(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("HospitalSideUVFinish.request"))return;File.Delete("HospitalSideUVFinish.request");try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var source=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()).Single(g=>g.name=="Building_06_01_Material #26_0");int fixedCount=0;foreach(var f in source.GetComponentsInChildren<MeshFilter>()){var m=f.sharedMesh;var p=m.vertices;var ids=m.triangles;var uv=m.uv;for(int k=0;k<ids.Length;k+=3){var a=source.transform.TransformPoint(p[ids[k]]);var b=source.transform.TransformPoint(p[ids[k+1]]);var c=source.transform.TransformPoint(p[ids[k+2]]);var n=Vector3.Cross(b-a,c-a).normalized;if(Mathf.Abs(n.z)<.65f)continue;bool upper=(a.y+b.y+c.y)/3>46;foreach(int v in new[]{ids[k],ids[k+1],ids[k+2]}){var w=source.transform.TransformPoint(p[v]);uv[v]=new Vector2(Mathf.Lerp(.17f,.83f,Mathf.InverseLerp(-200.9192f,-115.2816f,w.x)),Mathf.Lerp(.72f,.975f,Mathf.InverseLerp(upper?45.7f:27.6664f,upper?59.47861f:45.7f,w.y)));}fixedCount++;}m.uv=uv;m.RecalculateTangents();EditorUtility.SetDirty(m);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.AppendAllText("FinalEnvironmentRoadReview/CityHospitalUpgrade.txt","\nSide UVs corrected: window rows remain horizontal and continuous, triangles="+fixedCount+". No geometry changes.");File.WriteAllText("HospitalVerify.request","run");}catch(Exception e){File.AppendAllText("FinalEnvironmentRoadReview/CityHospitalUpgrade.txt",e.ToString());}}}
